% MATLAB Reference Script for Drag Coefficient Determination

% Fixed parameters
Dp = 0.0124;      % Particle diameter (m)
rho = 880.0;      % Liquid density (kg/m^3)
mu = 0.01232;     % Viscosity (kg/(m*s))
g = 9.81;         % Gravity (m/s^2)

% Projected area
A = (pi / 4) * Dp^2;

% Observations
distance = [0.28, 0.28, 0.28]; % m
time_s = [0.94, 0.97, 1.01];   % s

% Calculations
v = distance ./ time_s;
FD = 3 * pi * mu * Dp .* v;
N_Re = (rho .* v .* Dp) ./ mu;
CD = (2 .* FD) ./ (rho .* A .* (v .^ 2));

mean_CD = mean(CD);
fprintf('Mean Drag Coefficient CD = %.4f\n', mean_CD);

% Plotting
figure;
plot(N_Re, CD, 'o-', 'Color', [0 0.447 0.741], 'LineWidth', 1.8, 'MarkerSize', 8, 'DisplayName', 'Observed Data');
hold on;
p = polyfit(N_Re, CD, 1);
N_fit = linspace(min(N_Re), max(N_Re), 100);
plot(N_fit, polyval(p, N_fit), '--', 'Color', [0.85 0.325 0.098], 'LineWidth', 1.5, 'DisplayName', 'Trendline');
grid on; box on;
xlabel('Particle Reynolds Number (NRe)');
ylabel('Drag Coefficient (CD)');
title('Drag Coefficient vs Reynolds Number (CD vs NRe)');
legend('Location', 'northeast');
